def solve(rows):
  """Calculates the cost of rows according to the given rules."""
  audit_positions = [(i, row) for i, row in enumerate(rows)]
  filtered_positions = [(i, row) for i, row in audit_positions if i % 3 != 1 or i == len(rows) - 1]

  if not filtered_positions:
    return 0

  rotated_rows = []
  for i, row in filtered_positions:
    rotated_rows.insert(0, row)

  if not rotated_rows:
    return 0

  total_cost = 0
  for row in rotated_rows:
    if row >= 0:
      cost = 0
      if row < 19:
        cost = 3 * row
      else:
        cost = 3 * 19 + (row - 19) * 2
      if cost <= 70:
        total_cost += cost
        row -= cost
      else:
        total_cost += 70
        row = 0

  return total_cost

